import { Loader } from '@mantine/core'
import { IconRotateClockwise, IconX, IconArrowUp, IconArrowDown } from '@tabler/icons-react'
import * as pageCache from '../lib/pageCache'
import { ITEM_PADDING, LABEL_HEIGHT } from '../constants'
import styles from './PageThumbnail.module.css'

interface Props {
  src: string | undefined
  pdfPath: string
  page: number
  thumbHeight: number
  isSelected: boolean
  isSkipped: boolean
  rotation: number
  label: string
  onClick: () => void
  onRotate?: () => void
  onToggleSkip?: () => void
  canMoveUp?: boolean
  canMoveDown?: boolean
  onMoveUp?: () => void
  onMoveDown?: () => void
}

export default function PageThumbnail({
  src, pdfPath, page, thumbHeight,
  isSelected, isSkipped, rotation, label,
  onClick, onRotate, onToggleSkip,
  canMoveUp, canMoveDown, onMoveUp, onMoveDown,
}: Props) {
  const isRotated = rotation !== 0
  const isOddRotation = rotation === 90 || rotation === 270
  const imgTransform = rotation ? `rotate(${rotation}deg)${isOddRotation ? ` scale(${210 / 297})` : ''}` : undefined
  const showMoveButtons = onMoveUp !== undefined || onMoveDown !== undefined

  return (
    <div className={styles.wrapper} style={{ padding: ITEM_PADDING, paddingBottom: 0 }} onClick={onClick}>
      <div className={`${styles.frame} ${isSelected ? styles.frameSelected : ''}`}>
        <div className={styles.imageContainer}>
          {src ? (
            <img
              src={src}
              alt={`page ${page}`}
              className={styles.image}
              style={{ opacity: isSkipped ? 0.3 : 1, transform: imgTransform }}
              draggable={false}
            />
          ) : (
            <div className={styles.placeholder} style={{ height: thumbHeight }}>
              {pageCache.isLoading(pdfPath, page) && <Loader size="xs" />}
            </div>
          )}
        </div>
        {onRotate && (
          <ThumbnailIconButton
            ariaLabel="Rotate page clockwise"
            onClick={onRotate}
            position={{ top: 3, left: 3 }}
            active={isRotated}
            icon={<IconRotateClockwise size={10} stroke={3} />}
          />
        )}
        {onToggleSkip && (
          <ThumbnailIconButton
            ariaLabel={isSkipped ? 'Unskip page' : 'Skip page'}
            onClick={onToggleSkip}
            position={{ top: 3, right: 3 }}
            active={isSkipped}
            activeColor="var(--mantine-color-orange-6)"
            icon={<IconX size={10} stroke={3} />}
          />
        )}
        {showMoveButtons && (
          <>
            <ThumbnailIconButton
              ariaLabel="Move page up"
              onClick={() => onMoveUp?.()}
              position={{ bottom: 3, left: 3 }}
              disabled={!canMoveUp}
              icon={<IconArrowUp size={10} stroke={3} />}
            />
            <ThumbnailIconButton
              ariaLabel="Move page down"
              onClick={() => onMoveDown?.()}
              position={{ bottom: 3, right: 3 }}
              disabled={!canMoveDown}
              icon={<IconArrowDown size={10} stroke={3} />}
            />
          </>
        )}
      </div>
      <div
        className={`${styles.label} ${isSkipped ? styles.labelSkipped : ''}`}
        style={{ height: LABEL_HEIGHT, lineHeight: `${LABEL_HEIGHT}px` }}
      >
        {label}
      </div>
    </div>
  )
}

interface ThumbnailIconButtonProps {
  ariaLabel: string
  onClick: () => void
  icon: React.ReactNode
  position: { top?: number; bottom?: number; left?: number; right?: number }
  active?: boolean
  activeColor?: string
  disabled?: boolean
}

function ThumbnailIconButton({
  ariaLabel, onClick, icon, position,
  active = false, activeColor = 'var(--mantine-color-blue-6)', disabled = false,
}: ThumbnailIconButtonProps) {
  return (
    <button
      type="button"
      aria-label={ariaLabel}
      disabled={disabled}
      onClick={(e) => { e.stopPropagation(); onClick() }}
      className={`${styles.iconBtn} ${active ? styles.iconBtnActive : ''} ${disabled ? styles.iconBtnDisabled : ''}`}
      style={{
        ...position,
        background: active ? activeColor : 'rgba(0,0,0,0.45)',
        cursor: disabled ? 'default' : 'pointer',
      }}
    >
      {icon}
    </button>
  )
}

import { useRef, useEffect } from 'react'
import { TransformWrapper, TransformComponent, ReactZoomPanPinchRef } from 'react-zoom-pan-pinch'
import { Center, Loader } from '@mantine/core'
import * as pageCache from '../lib/pageCache'
import styles from './DetailPanel.module.css'

const DETAIL_WIDTH = 1400

interface Props {
  pdfPath: string
  pageNum: number
  pageCount: number
  rotation?: number
  onToggleSkip?: () => void
  onRotate?: (delta: 90 | -90) => void
}

export default function DetailPanel({ pdfPath, pageNum, pageCount, rotation = 0, onToggleSkip, onRotate }: Props) {
  pageCache.usePageCacheRender()
  const transformRef = useRef<ReactZoomPanPinchRef>(null)

  useEffect(() => {
    pageCache.load(pdfPath, pageNum, DETAIL_WIDTH)
    if (pageNum > 1) pageCache.load(pdfPath, pageNum - 1, DETAIL_WIDTH) // prefetch previous page
    if (pageNum < pageCount) pageCache.load(pdfPath, pageNum + 1, DETAIL_WIDTH) // prefetch next page
  }, [pdfPath, pageNum, pageCount])

  useEffect(() => {
    transformRef.current?.resetTransform()
  }, [pageNum, rotation])

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return
      if (e.key.toLowerCase() !== 'r') return
      e.preventDefault()
      onRotate?.(e.shiftKey ? -90 : 90)
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [onRotate])

  const cachedWidth = pageCache.getCachedWidth(pdfPath, pageNum)
  const src = cachedWidth !== undefined && cachedWidth >= DETAIL_WIDTH
    ? pageCache.getSrc(pdfPath, pageNum)
    : undefined

  return (
    <div className={styles.panel}>
      {pageCache.isLoading(pdfPath, pageNum) && (
        <Center className={styles.loaderCenter}>
          <Loader />
        </Center>
      )}
      {src && (
        <TransformWrapper ref={transformRef} centerOnInit minScale={0.1} maxScale={8}>
          <TransformComponent wrapperClass={styles.wrapper} contentClass={styles.content}>
            <img
              src={src}
              alt={`Page ${pageNum}`}
              draggable={false}
              className={styles.image}
              style={{ transform: rotation ? `rotate(${rotation}deg)` : undefined }}
            />
          </TransformComponent>
        </TransformWrapper>
      )}
    </div>
  )
}

import { useRef } from 'react'
import { Text, TextProps, Tooltip } from '@mantine/core'
import { useIsTruncated } from '../lib/useIsTruncated'

interface Props extends Omit<TextProps, 'children' | 'truncate'> {
  children: React.ReactNode
  label: string
}

// Renders children as truncating text, showing a tooltip with label only
// once the text is actually clipped - same technique as ClippedPath.tsx.
// label is separate from children since children may include a decorative
// prefix (e.g. an icon) that shouldn't appear in the tooltip.
export default function TruncatedText({ children, label, ...textProps }: Props) {
  const ref = useRef<HTMLParagraphElement>(null)
  const truncated = useIsTruncated(ref, label)

  const text = (
    <Text ref={ref} truncate="end" {...textProps}>
      {children}
    </Text>
  )

  return truncated ? <Tooltip label={label} openDelay={500}>{text}</Tooltip> : text
}

